// Package schema emits the JSON Schema an editor uses for completion and
// inline errors, via the yaml-language-server header in menubar.yaml.
package schema

// JSON is the schema for menubar.yaml. It mirrors what spec.Parse accepts;
// where the two could drift, spec.Parse is the authority.
func JSON() string { return body }

const body = `{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "menubar.yaml",
  "description": "A macOS menu bar app, generated by perch.",
  "type": "object",
  "required": ["app", "menu"],
  "additionalProperties": false,
  "properties": {
    "app": {
      "type": "object",
      "required": ["name", "id", "icon", "interval"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "description": "Bundle and executable name."},
        "id": {"type": "string", "description": "Bundle identifier, e.g. dev.example.menubar."},
        "icon": {"type": "string", "description": "SF Symbol name."},
        "interval": {"type": "string", "pattern": "^[0-9]+(ns|us|ms|s|m|h)$", "description": "Poll interval, e.g. 5s."}
      }
    },
    "watch": {
      "type": "object",
      "description": "Named sources, polled concurrently every interval.",
      "additionalProperties": {
        "type": "object",
        "additionalProperties": false,
        "oneOf": [
          {"required": ["run"]},
          {"required": ["http"]},
          {"required": ["exists"]}
        ],
        "properties": {
          "run": {"type": "array", "items": {"type": "string"}, "description": "argv, never a shell."},
          "http": {"type": "string", "description": "URL; .ok is a 2xx."},
          "exists": {"type": "string", "description": "Path; binds .ok only."},
          "json": {"type": "boolean", "description": "Decode the output into .data."},
          "shape": {"$ref": "#/definitions/shape"}
        }
      }
    },
    "status": {
      "type": "array",
      "description": "First matching rule wins.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "when": {"type": "string", "description": "CEL condition; omit to always match."},
          "icon": {"type": "string", "description": "SF Symbol name."},
          "dim": {"type": "boolean"},
          "badge": {"type": "string", "description": "CEL expression shown beside the icon."}
        }
      }
    },
    "menu": {"$ref": "#/definitions/menu"}
  },
  "definitions": {
    "shape": {
      "description": "What a command prints: string, int, double, bool, any, objects, and [T].",
      "oneOf": [
        {"type": "string", "enum": ["string", "int", "double", "bool", "any"]},
        {"type": "array", "minItems": 1, "maxItems": 1, "items": {"$ref": "#/definitions/shape"}},
        {"type": "object", "additionalProperties": {"$ref": "#/definitions/shape"}}
      ]
    },
    "menu": {
      "type": "array",
      "items": {
        "oneOf": [
          {"type": "string", "enum": ["separator"]},
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "text": {"type": "string", "description": "Label; {{ }} holes are CEL."},
              "when": {"type": "string", "description": "CEL condition deciding whether the item appears."},
              "each": {"type": "string", "description": "CEL list expression; the element binds to it."},
              "menu": {"$ref": "#/definitions/menu"},
              "run": {"type": "array", "items": {"type": "string"}, "description": "argv, never a shell."},
              "open": {"type": "string", "description": "URL or path."},
              "post": {
                "type": "object",
                "required": ["url"],
                "additionalProperties": false,
                "properties": {"url": {"type": "string"}, "body": {}}
              },
              "quit": {"type": "boolean"}
            }
          }
        ]
      }
    }
  }
}
`
